class Solution:
    def minCut(self, s: str) -> int:
        n = len(s)
        dp = list(range(n))

        for mid in range(n):
            l, r = mid, mid
            while l >= 0 and r < n and s[l] == s[r]:
                dp[r] = 0 if l == 0 else min(dp[r], dp[l - 1] + 1)
                l -= 1
                r += 1
            l, r = mid, mid + 1
            while l >= 0 and r < n and s[l] == s[r]:
                dp[r] = 0 if l == 0 else min(dp[r], dp[l - 1] + 1)
                l -= 1
                r += 1

        return dp[-1]

class Solution {
public:
    int minCut(string s) {
        int n = s.size();
        vector<int> dp(n);
        for (int i = 0; i < n; i++) dp[i] = i;
        for (int mid = 0; mid < n; mid++) {
            int l = mid, r = mid;
            while (l >= 0 && r < n && s[l] == s[r]) {
                dp[r] = (l == 0) ? 0 : min(dp[r], dp[l - 1] + 1);
                l--; r++;
            }
            l = mid; r = mid + 1;
            while (l >= 0 && r < n && s[l] == s[r]) {
                dp[r] = (l == 0) ? 0 : min(dp[r], dp[l - 1] + 1);
                l--; r++;
            }
        }
        return dp[n - 1];
    }
};

class Solution {
    public int minCut(String s) {
        int n = s.length();
        int[] dp = new int[n];
        for (int i = 0; i < n; i++) dp[i] = i;
        for (int mid = 0; mid < n; mid++) {
            int l = mid, r = mid;
            while (l >= 0 && r < n && s.charAt(l) == s.charAt(r)) {
                dp[r] = (l == 0) ? 0 : Math.min(dp[r], dp[l - 1] + 1);
                l--; r++;
            }
            l = mid; r = mid + 1;
            while (l >= 0 && r < n && s.charAt(l) == s.charAt(r)) {
                dp[r] = (l == 0) ? 0 : Math.min(dp[r], dp[l - 1] + 1);
                l--; r++;
            }
        }
        return dp[n - 1];
    }
}

