    const n = s.length;
    const dp = Array.from({ length: n }, (_, i) => i);
    for (let mid = 0; mid < n; mid++) {
        let l = mid, r = mid;
        while (l >= 0 && r < n && s[l] === s[r]) {
            dp[r] = (l === 0) ? 0 : Math.min(dp[r], dp[l - 1] + 1);
            l--; r++;
        }
        l = mid; r = mid + 1;
